import sys
from collections import deque

n, s, e = map(int, sys.stdin.read().split())
adj = {}
cnt = [0]

def build(order):
    # returns the id of the root (pre-order numbering) or None
    if order == 0:
        return None
    me = cnt[0]
    cnt[0] += 1
    adj[me] = {}
    left = build(order - 2) if order >= 2 else None
    right = build(order - 1)
    if left is not None:
        adj[me]['L'] = left
        adj[left]['U'] = me
    if right is not None:
        adj[me]['R'] = right
        adj[right]['U'] = me
    return me

if n > 14:
    # too big to build: recurse on subtree sizes instead
    size = [0, 1]
    for i in range(2, n + 1):
        size.append(1 + size[i - 2] + size[i - 1])

    def down(order, k):
        # moves from the root of T_order to node k
        if k == 0:
            return ''
        k -= 1
        if k < size[order - 2]:
            return 'L' + down(order - 2, k)
        return 'R' + down(order - 1, k - size[order - 2])

    def up(order, k):
        return 'U' * len(down(order, k))

    def solve(order, a, b):
        if a == b:
            return ''
        if a == 0:
            return down(order, b)
        if b == 0:
            return up(order, a)
        a -= 1
        b -= 1
        ls = size[order - 2]
        if a < ls and b < ls:
            return solve(order - 2, a, b)
        if a >= ls and b >= ls:
            return solve(order - 1, a - ls, b - ls)
        if a < ls:
            return up(order - 2, a) + 'U' + 'R' + down(order - 1, b - ls)
        return up(order - 1, a - ls) + 'U' + 'L' + down(order - 2, b)

    print(solve(n, s, e))
    sys.exit(0)

